```python
import re

_NUMBER_RE = re.compile(r"^-?\d+$")


class StackUnderflowError(Exception):
    pass


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(count)]


def evaluate(input_data):
    stack = []
    words = {}

    def _binary(op):
        def action():
            b, a = _pop(stack, 2)
            stack.append(op(a, b))
        return action

    def _trunc_div(a, b):
        if b == 0:
            raise ZeroDivisionError("divide by zero")
        q = a // b
        if a % b != 0 and (a < 0) != (b < 0):
            q += 1
        return q

    words.update({
        "+": [_binary(operator.add)],
        "-": [_binary(operator.sub)],
        "*": [_binary(operator.mul)],
        "/": [_binary(_trunc_div)],
        "dup": [lambda... ]
    })
```

Hmm, lambdas inside a dict literal are evaluated immediately — that's fine since they close over stack. But `_pop` is defined at module level and takes stack as an argument. Let me restructure: the action functions take the stack as a parameter? Simpler: define the builtins inside evaluate as closures.

