            b, a = _pop(2)
            stack.append(fn(a, b))
        return action

    def _div(a, b):
        if b == 0:
            raise ZeroDivisionError("divide by zero")
        q = a // b
        if a % b != 0 and (a < 0) != (b < 0):
            q += 1
        return q

    words = {
        "+": [_binary(operator.add)],
        "-": [_binary(operator.sub)],
        "*": [_binary(operator.mul)],
        "/": [_binary(_div)],
        "dup": [lambda: stack.append(stack[-1]) ... ]
    }
```

